def _recipes() -> list[dict]:
    raw = zlib.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8")
    return json.loads(raw)


def upgrade() -> None:
    rows = _recipes()
    stmt = sa.text(
        """
        INSERT INTO recipes (id, data, owner_id, is_public, is_official, parent_recipe_id)
        VALUES (:id, CAST(:data AS jsonb), :owner_id, :is_public, :is_official, :parent_recipe_id)
        ON CONFLICT (id) DO NOTHING
        """
    )
    op.get_bind().execute(
        stmt,
        [
            {
                "id": row["id"],
                "data": json.dumps(row["data"], ensure_ascii=False),
                "owner_id": row["owner_id"],
                "is_public": row["is_public"],
                "is_official": row["is_official"],
                "parent_recipe_id": row["parent_recipe_id"],
            }
            for row in rows
        ],
    )


def downgrade() -> None:
    # Removes every id in the snapshot, including rows that already existed before upgrade.
    ids = [row["id"] for row in _recipes()]
    stmt = sa.text("DELETE FROM recipes WHERE id IN :ids").bindparams(
        sa.bindparam("ids", expanding=True)
    )
    op.get_bind().execute(stmt, {"ids": ids})
